<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { listTemplates } from '../api/templates'
import { createReport, deleteReport, listReportSummaries, pageReports, updateReport, type ReportSummary } from '../api/reports'
import type { Report, Template } from '../types'

const templates = ref<Template[]>([]); const summaries = ref<ReportSummary[]>([]); const queryTemplateId = ref(''); const detailTemplate = ref<Template | null>(null); const detailReporter = ref<ReportSummary | null>(null); const detailRecords = ref<Report[]>([]); const page = ref(0); const size = ref(10); const total = ref(0); const totalPages = ref(0); const loading = ref(false); const detailLoading = ref(false); const error = ref(''); const message = ref(''); const editingId = ref<Report['id'] | null>(null); const creating = ref(false); const editData = ref<Record<string, string>>({}); const keyword = ref(''); const statusFilter = ref('')
const visibleSummaries = computed(() => queryTemplateId.value ? summaries.value.filter((item) => String(item.templateId) === queryTemplateId.value) : summaries.value)
const detailColumns = computed(() => detailTemplate.value?.columns || [])
function text(e: unknown) { return e instanceof Error ? e.message : '操作失败' }
function objectData(data: Report['data']) { if (!data) return {}; if (typeof data === 'object') return data as Record<string, unknown>; try { return JSON.parse(data) as Record<string, unknown> } catch { return {} } }
function formatDate(value?: string) { return value ? value.replace('T', ' ').replace(/\.\d+$/, '') : '-' }
function statusText(value?: string) { return value === 'SUBMITTED' ? '已提交' : value === 'DRAFT' ? '草稿' : value === 'APPROVED' ? '已审核' : value || '-' }
function pageLabel() { return total.value ? `第 ${page.value + 1} / ${totalPages.value} 页，共 ${total.value} 条` : '暂无数据' }
const filteredRecords = computed(() => detailRecords.value.filter(record => {
  if (statusFilter.value && record.status !== statusFilter.value) return false
  if (!keyword.value.trim()) return true
  return Object.values(objectData(record.data)).some(value => String(value ?? '').toLowerCase().includes(keyword.value.trim().toLowerCase()))
}))
const numericTotals = computed(() => detailColumns.value.filter(column => column.type === 'number' || column.type === 'money').map(column => ({ label: column.label, total: filteredRecords.value.reduce((sum, record) => sum + (Number(String(objectData(record.data)[column.key] ?? '').replace(/,/g, '')) || 0), 0) })))
async function loadTemplates() { try { templates.value = await listTemplates() } catch (e) { error.value = text(e) } }
async function loadSummaries() { loading.value = true; try { summaries.value = await listReportSummaries() } catch (e) { error.value = text(e) } finally { loading.value = false } }
async function openDetail(summary: ReportSummary) { const template = templates.value.find((item) => String(item.id) === String(summary.templateId)); if (!template) { error.value = '未找到对应模板'; return }; detailTemplate.value = template; detailReporter.value = summary; page.value = 0; editingId.value = null; creating.value = false; keyword.value = ''; statusFilter.value = ''; await loadDetail() }
function closeDetail() { detailTemplate.value = null; detailReporter.value = null; detailRecords.value = []; editingId.value = null; creating.value = false }
async function loadDetail() { if (!detailTemplate.value) return; detailLoading.value = true; error.value = ''; try { const result = await pageReports({ templateId: detailTemplate.value.id, reporterId: detailReporter.value!.reporterId, page: page.value, size: size.value }); detailRecords.value = result.records; total.value = result.total; totalPages.value = result.totalPages } catch (e) { error.value = text(e) } finally { detailLoading.value = false } }
function changeSize() { page.value = 0; loadDetail() }
function previous() { if (page.value > 0) { page.value--; loadDetail() } }
function next() { if (page.value + 1 < totalPages.value) { page.value++; loadDetail() } }
function edit(record: Report) { editData.value = Object.fromEntries(detailColumns.value.map((column) => [column.key, String(objectData(record.data)[column.key] ?? '')])); editingId.value = record.id; creating.value = false }
function cancelEdit() { editingId.value = null; creating.value = false }
function addRow() { if (!detailTemplate.value) return; editData.value = Object.fromEntries(detailColumns.value.map((column) => [column.key, ''])); creating.value = true; editingId.value = null }
function validData() { if (detailColumns.value.filter((column) => column.required).some((column) => !String(editData.value[column.key] ?? '').trim())) { error.value = '请填写必填字段'; return false }; return true }
async function save(record?: Report) { if (!detailTemplate.value || !validData()) return; try { if (record) await updateReport(record.id, { templateId: detailTemplate.value.id, data: editData.value, status: record.status || 'SUBMITTED' }); else await createReport({ templateId: detailTemplate.value.id, data: editData.value, status: 'SUBMITTED' }); message.value = record ? '填报数据已更新' : '已新增一行填报数据'; cancelEdit(); await Promise.all([loadDetail(), loadSummaries()]) } catch (e) { error.value = text(e) } }
async function remove(record: Report) { if (!window.confirm('确认删除该行填报数据吗？')) return; try { await deleteReport(record.id); message.value = '填报数据已删除'; if (detailRecords.value.length === 1 && page.value > 0) page.value--; await Promise.all([loadDetail(), loadSummaries()]) } catch (e) { error.value = text(e) } }
onMounted(async () => { await loadTemplates(); await loadSummaries() })
</script>

<template><section><div class="page-heading"><div><h1>填报数据</h1><p>外层仅显示模板汇总，查看明细后每一行对应 Excel 中的一行数据。</p></div></div><div class="filters"><select v-model="queryTemplateId"><option value="">全部模板</option><option v-for="item in templates" :key="item.id" :value="String(item.id)">{{ item.name }}</option></select><button class="primary" @click="loadSummaries">刷新</button></div><div v-if="message" class="notice success">{{ message }}</div><div v-if="error" class="notice error">{{ error }}</div><div class="table-wrap summary-table"><table><thead><tr><th>模板</th><th>填报人</th><th>数据条数</th><th class="fixed-action">操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="4" class="muted">加载中...</td></tr><tr v-else-if="!visibleSummaries.length"><td colspan="4" class="muted">暂无填报数据。</td></tr><tr v-for="summary in visibleSummaries" :key="`${summary.templateId}-${summary.reporterId}`"><td>{{ summary.templateName }}</td><td>{{ summary.reporterName }}</td><td>{{ summary.recordCount }}</td><td class="fixed-action"><button class="text-button" @click="openDetail(summary)">查看明细</button></td></tr></tbody></table></div><div v-if="detailTemplate" class="modal-backdrop" @click.self="closeDetail"><section class="detail-modal"><header class="detail-modal-header"><div><h2>{{ detailTemplate.name }} - {{ detailReporter?.reporterName }}明细</h2><p>{{ pageLabel() }}，一行对应一条 Excel 数据。</p></div><button class="text-button" @click="closeDetail">关闭</button></header><div class="detail-toolbar"><button class="primary" :disabled="creating" @click="addRow">新增一行</button><label>关键词<input v-model.trim="keyword" placeholder="筛选当前页字段" /></label><label>状态<select v-model="statusFilter"><option value="">全部</option><option value="DRAFT">草稿</option><option value="SUBMITTED">已提交</option><option value="APPROVED">已审核</option></select></label><label>每页<select v-model.number="size" @change="changeSize"><option :value="10">10</option><option :value="20">20</option><option :value="50">50</option></select> 条</label></div><p class="hint">当前页筛选 {{ filteredRecords.length }} 条<span v-if="numericTotals.length">；{{ numericTotals.map(item => `${item.label}合计 ${item.total}`).join('，') }}</span></p><div class="detail-table-scroll"><table class="detail-report-table"><thead><tr><th class="fixed-index">#</th><th>填报人</th><th v-for="column in detailColumns" :key="column.key">{{ column.label }}</th><th>提交时间</th><th>状态</th><th class="fixed-action">操作</th></tr></thead><tbody><tr v-if="creating" class="editing-row"><td class="fixed-index">新增</td><td>当前用户</td><td v-for="column in detailColumns" :key="column.key"><textarea v-if="column.type === 'textarea'" v-model="editData[column.key]" rows="1" /><input v-else v-model="editData[column.key]" :type="column.type === 'number' ? 'number' : column.type === 'date' ? 'date' : column.type === 'month' ? 'month' : 'text'" /></td><td>-</td><td>草稿</td><td class="fixed-action"><button class="text-button" @click="save()">保存</button><button class="danger-button" @click="cancelEdit">取消</button></td></tr><tr v-if="detailLoading"><td :colspan="detailColumns.length + 5" class="muted">加载中...</td></tr><tr v-else-if="!filteredRecords.length && !creating"><td :colspan="detailColumns.length + 5" class="muted">暂无符合条件的数据。</td></tr><tr v-for="(record, index) in filteredRecords" :key="record.id" :class="{ 'editing-row': editingId === record.id }"><td class="fixed-index">{{ page * size + index + 1 }}</td><td>{{ record.reporterName || '-' }}</td><td v-for="column in detailColumns" :key="column.key"><textarea v-if="editingId === record.id && column.type === 'textarea'" v-model="editData[column.key]" rows="1" /><input v-else-if="editingId === record.id" v-model="editData[column.key]" :type="column.type === 'number' ? 'number' : column.type === 'date' ? 'date' : column.type === 'month' ? 'month' : 'text'" /><span v-else>{{ String(objectData(record.data)[column.key] ?? '-') }}</span></td><td>{{ formatDate(record.updatedAt) }}</td><td>{{ statusText(record.status) }}</td><td class="fixed-action"><template v-if="editingId === record.id"><button class="text-button" @click="save(record)">保存</button><button class="danger-button" @click="cancelEdit">取消</button></template><template v-else><button class="text-button" :disabled="creating" @click="edit(record)">修改</button><button class="danger-button" :disabled="creating" @click="remove(record)">删除</button></template></td></tr></tbody></table></div><footer class="detail-pagination"><button class="secondary" :disabled="page === 0 || detailLoading" @click="previous">上一页</button><span>{{ pageLabel() }}</span><button class="secondary" :disabled="page + 1 >= totalPages || detailLoading" @click="next">下一页</button></footer></section></div></section></template>
